package com.example.agendapersonal.ui;
import android.app.*;import android.content.*;import android.os.Bundle;import android.widget.*;
import com.example.agendapersonal.R;import com.example.agendapersonal.ui.registro.*;import com.example.agendapersonal.util.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;

public class AjustesActivity extends com.example.agendapersonal.ui.ActividadTematica {
 private MenuNavegacion menu;private Spinner tablas;private TextView estado;private String tablaPendiente;private final ExecutorService trabajo=Executors.newSingleThreadExecutor();
 private static final String[] TABLAS={"personas","direcciones","materias","estudios","clasificaciones_sociales","sociales","especialidades","salud","trabajo","freelance","clasificaciones_economia","ingresos","pagos","gastos","ejercicios","ambitos_emocionales","motivos_emocionales","registros_emocionales","frases_personales","eventos","tareas","registros_investigacion","observaciones_ri"};
 @Override protected void onCreate(Bundle b){super.onCreate(b);menu=new MenuNavegacion(this);setContentView(menu.getRaiz());menu.establecerContenido(R.layout.activity_ajustes);findViewById(R.id.botonMenu).setOnClickListener(v->menu.alternar());tablas=findViewById(R.id.tablaCsv);estado=findViewById(R.id.estadoAjustes);List<String> nombres=new ArrayList<>();for(String t:TABLAS)nombres.add(Definicion.de(t).titulo);tablas.setAdapter(new ArrayAdapter<>(this,com.example.agendapersonal.R.layout.item_opcion_tema,nombres));if(b!=null){tablaPendiente=b.getString("tablaPendiente");tablas.setSelection(b.getInt("tabla",0));}
  Spinner selector=findViewById(R.id.selectorTema);selector.setAdapter(new ArrayAdapter<>(this,com.example.agendapersonal.R.layout.item_opcion_tema,Tema.NOMBRES));selector.setSelection(Tema.elegido(this));
  findViewById(R.id.aplicarTema).setOnClickListener(v->{int elegido=selector.getSelectedItemPosition();if(elegido!=Tema.elegido(this)){Tema.guardar(this,elegido);Tema.aplicar(getApplicationContext());com.example.agendapersonal.avisos.ProgramadorAvisos.actualizar(this);recreate();}});
  EditText escala=findViewById(R.id.escalaRadar);escala.setText(String.valueOf(getSharedPreferences("agenda_preferencias",MODE_PRIVATE).getInt("escala_radar",10)));
  findViewById(R.id.guardarEscala).setOnClickListener(v->{try{int valor=Integer.parseInt(escala.getText().toString());if(valor<1||valor>1000000)throw new NumberFormatException();getSharedPreferences("agenda_preferencias",MODE_PRIVATE).edit().putInt("escala_radar",valor).apply();estado.setText("Escala del radar guardada");}catch(NumberFormatException e){escala.setError("Ingresá una escala entre 1 y 1000000");}});
  findViewById(R.id.abrirRespaldo).setOnClickListener(v->startActivity(new Intent(this,RespaldoActivity.class)));
  findViewById(R.id.abrirAvisos).setOnClickListener(v->startActivity(new Intent(this,NotificacionesActivity.class)));
  findViewById(R.id.abrirConexion).setOnClickListener(v->startActivity(new Intent(this,ConexionActivity.class)));
  findViewById(R.id.exportarCsv).setOnClickListener(v->{tablaPendiente=TABLAS[tablas.getSelectedItemPosition()];Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"agenda_"+tablaPendiente+".csv");startActivityForResult(i,1);});
  findViewById(R.id.importarHistorico).setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");startActivityForResult(i,3);});
  findViewById(R.id.importarCsv).setOnClickListener(v->{tablaPendiente=TABLAS[tablas.getSelectedItemPosition()];Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");startActivityForResult(i,2);});
 }
 private String device(){return getSharedPreferences("agenda_identidad",MODE_PRIVATE).getString("device_id","");}
 private String owner(){return com.example.agendapersonal.sync.IdentidadLocal.propietario(this);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null||(request!=3&&tablaPendiente==null))return;final android.net.Uri uri=data.getData();final String tabla=tablaPendiente;estado.setText("Procesando archivo…");
  trabajo.execute(()->{try{
   if(request==3){org.json.JSONObject paquete=com.example.agendapersonal.data.ImportadorHistorico.leer(getContentResolver().openInputStream(uri));int cantidad=paquete.getJSONArray("records").length(),pendientes=paquete.getJSONArray("review").length();runOnUiThread(()->{if(isFinishing()||isDestroyed())return;estado.setText("Paquete histórico validado");new AlertDialog.Builder(this).setTitle("Importar agenda anterior").setMessage("El paquete contiene "+cantidad+" registros y catálogos preparados y "+pendientes+" filas para revisar. Se conservarán los datos de origen. Los identificadores existentes se omiten y cualquier error cancela toda la carga.").setNegativeButton("Cancelar",null).setPositiveButton("Importar",(d,w)->{estado.setText("Importando agenda anterior…");trabajo.execute(()->{try{com.example.agendapersonal.data.ImportadorHistorico.Resultado r=com.example.agendapersonal.data.ImportadorHistorico.importar(this,paquete,device(),owner());informar(r.resumen());}catch(Exception e){android.util.Log.e("AgendaPersonal","Importación histórica",e);informar("No se importaron registros. Revisá el paquete y sus relaciones.");}});}).show();});}
   else if(request==1){try(Fuente fuente=Fuentes.abrir(this,device(),tabla);Writer out=new OutputStreamWriter(getContentResolver().openOutputStream(uri),StandardCharsets.UTF_8)){List<Registro> registros=fuente.todos();List<String> cabecera=new ArrayList<>();cabecera.add("id");for(Campo c:Definicion.de(tabla).campos)cabecera.add(c.clave);Csv.escribir(out,cabecera);for(Registro r:registros){List<String>fila=new ArrayList<>();for(String c:cabecera)fila.add(r.texto(c));Csv.escribir(out,fila);}informar("Exportados "+registros.size()+" registros en CSV UTF-8.");}}
   else if(request==2){List<List<String>> filas;try(Reader in=new InputStreamReader(getContentResolver().openInputStream(uri),StandardCharsets.UTF_8)){filas=Csv.leer(in);}List<Registro> nuevos=preparar(tabla,filas);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;estado.setText("Archivo validado: "+nuevos.size()+" registros nuevos. Los identificadores existentes se omiten.");new AlertDialog.Builder(this).setTitle("Importar · "+Definicion.de(tabla).titulo).setMessage("Se agregarán "+nuevos.size()+" registros. No se reemplazan los existentes. Importá Personas y catálogos antes de sus actividades.").setNegativeButton("Cancelar",null).setPositiveButton("Importar",(d,w)->importar(tabla,nuevos)).show();});}
  }catch(Exception e){android.util.Log.e("AgendaPersonal","CSV",e);informar("No se pudo procesar el CSV: "+e.getMessage());}});
 }
 private List<Registro> preparar(String tabla,List<List<String>> filas){
  if(filas.isEmpty())throw new IllegalArgumentException("El archivo está vacío");Definicion d=Definicion.de(tabla);List<String> cabecera=filas.get(0);Set<String> permitidas=new HashSet<>();permitidas.add("id");for(Campo c:d.campos)permitidas.add(c.clave);
  if(new HashSet<>(cabecera).size()!=cabecera.size())throw new IllegalArgumentException("Hay columnas repetidas");for(String c:cabecera)if(!permitidas.contains(c))throw new IllegalArgumentException("Columna desconocida: "+c);for(Campo c:d.campos)if(c.obligatorio&&!cabecera.contains(c.clave))throw new IllegalArgumentException("Falta columna "+c.clave);
  Set<String> existentes=new HashSet<>();try(com.example.agendapersonal.data.DatabaseHelper h=new com.example.agendapersonal.data.DatabaseHelper(this);android.database.Cursor c=h.getReadableDatabase().query(d.tabla,new String[]{"id"},null,null,null,null,null)){while(c.moveToNext())existentes.add(c.getString(0));}
  List<Registro> nuevos=new ArrayList<>();for(int i=1;i<filas.size();i++){List<String>fila=filas.get(i);if(fila.size()==1&&fila.get(0).isEmpty())continue;if(fila.size()!=cabecera.size())throw new IllegalArgumentException("Fila "+(i+1)+": cantidad de columnas incorrecta");Registro r=new Registro();for(int k=0;k<cabecera.size();k++)r.put(cabecera.get(k),fila.get(k).isEmpty()?null:fila.get(k));String id=r.texto("id");if(!id.isEmpty()){UUID.fromString(id);if(existentes.contains(id))continue;existentes.add(id);}for(Campo c:d.campos){String valor=r.texto(c.clave);if(c.obligatorio&&valor.isEmpty())throw new IllegalArgumentException("Fila "+(i+1)+": falta "+c.etiqueta);if(c.tipo.equals("booleano")&&!valor.isEmpty()&&!valor.equals("true")&&!valor.equals("false"))throw new IllegalArgumentException("Fila "+(i+1)+": valor de alarma inválido");String error=ReglasAgenda.validarValor(c.tipo,valor);if(error!=null)throw new IllegalArgumentException("Fila "+(i+1)+": "+c.etiqueta+" · "+error);if(c.opciones.length>0&&!valor.isEmpty()&&!Arrays.asList(c.opciones).contains(valor))throw new IllegalArgumentException("Fila "+(i+1)+": opción inválida para "+c.etiqueta);if(c.tipo.equals("decimal"))r.put(c.clave,valor.isEmpty()?null:valor.replace(',','.'));}r.put("ownerId",owner());nuevos.add(r);}return nuevos;
 }
 private void importar(String tabla,List<Registro> nuevos){estado.setText("Importando…");trabajo.execute(()->{int cantidad=0;try(Fuente f=Fuentes.abrir(this,device(),tabla)){for(Registro r:nuevos){if(!f.guardar(r,true))throw new IllegalStateException("El repositorio rechazó el registro");cantidad++;}informar("Importados "+cantidad+" registros. Los cambios quedaron guardados localmente.");}catch(RuntimeException e){android.util.Log.e("AgendaPersonal","Importación",e);informar("Se guardaron "+cantidad+" de "+nuevos.size()+" registros. La importación se detuvo: revisá las relaciones con Personas y catálogos. No se modificaron registros anteriores.");}});}
 private void informar(String s){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())estado.setText(s);});}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("tablaPendiente",tablaPendiente);b.putInt("tabla",tablas.getSelectedItemPosition());}
 @Override public void onBackPressed(){if(menu.estaAbierto())menu.cerrar();else super.onBackPressed();}
 @Override protected void onDestroy(){trabajo.shutdown();super.onDestroy();}
}
